


/** Read-only order history row for merchant timeline rendering and debugging. The owning resource remains authoritative for state and money movement. */ export type OrderActivityInput = { /** Stable but open activity string. Flint documents exactly the values it emits today; clients must still render unknown future values gracefully. */ "activity_type": string; /** Change to the order balance narrated by this row. Informational rows have amount 0. Do not sum activity deltas to compute the order balance. */ "balance_delta_money": { /** Signed amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Related checkout session when activity_type points at checkout session lifecycle. */ "checkout_session_id"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; /** Human-readable Flint description. Provider-specific raw statuses and failure values are not exposed here. */ "description": string; "fulfillment_id"?: string; "order_activity_id": string; "order_charge_id"?: string; "order_discount_id"?: string; "order_line_item_id"?: string; "order_tip_id"?: string; /** Related payment intent when activity_type points at a payment attempt or payment outcome. */ "payment_intent_id"?: string; /** Related refund when activity_type points at a refund outcome. Read the refund for the authoritative outcome. */ "refund_id"?: string; /** Order balance after this activity in chronological time. This is context for reading the log, not a reconciliation ledger. */ "running_balance_money": { /** Signed amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; };
